# -*- coding: utf-8 -*-
"""一键更新（v2.3.42 起，macOS / Windows 共用，只用标准库）。

每次发布时，每个平台在 GitHub Release 上多放两个文件（scripts/make_update.py 生成）：
  update-<平台>.json         更新清单：版本号、更新说明、每个旧版本要换哪些文件、增量包的校验值
  update-<平台>-v<版本>.zip  增量包：所有支持的旧版本需要的新文件合集，按安装目录内的相对路径存放
清单文件名固定，用 releases/latest/download/ 总能拿到最新一版。

程序里的流程：
  check()         取清单，判断有没有新版、能不能自动装（当前版本在清单的 bases 里才能自动装）
  prepare()       后台下载增量包（断点续传、校验 sha256），只解出本机需要的文件到暂存目录
  launch_apply()  启动独立的替换程序；它等本程序退出后再换文件，失败自动还原，可选换完重新打开
  on_startup()    新版本启动时读上次替换的结果、清理暂存和备份

替换程序：
  macOS    /bin/bash 脚本：把整个 App 克隆一份（APFS 上是瞬时的）→ 放入新文件 → codesign 校验
           → 两次改名整包换上（旧包移进缓存目录）。替换前后任何一步失败，原来的 App 不动。
  Windows  把自带的 Python 运行环境复制到临时目录，用它运行本文件的 --apply：逐个文件先备份再替换、
           替换后校验 sha256，任何一步失败按备份还原。不用安装目录里的运行环境，是因为它正被占用。
"""
import hashlib
import json
import os
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import zipfile
from pathlib import Path

RELEASE_BASE = "https://github.com/AaronGIG/pdf2zh-desktop/releases"
UA = "pdf2zh-desktop-updater"
ENV_MANIFEST = "PDF2ZH_UPDATE_MANIFEST"   # 测试用：清单地址（http(s):// 或本地文件路径），优先于 GitHub


class UpdateError(Exception):
    pass


class UpdateCancelled(UpdateError):
    pass


# ───────────────────────── 基础工具 ─────────────────────────

def platform_key():
    return "mac" if sys.platform == "darwin" else "win"


def vtuple(v):
    try:
        return tuple(int(x) for x in str(v).strip().lstrip("vV").split("."))
    except Exception:
        return (0,)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _is_url(s):
    return str(s).startswith(("http://", "https://"))


def _read(src, timeout=15):
    """读清单：网址或本地文件"""
    if _is_url(src):
        import urllib.request
        req = urllib.request.Request(src, headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read()
    with open(src, "rb") as f:
        return f.read()


def install_root():
    """当前程序的安装位置；不是打包好的安装（开发环境）返回 None。
    macOS 是 .app 包本身，Windows 是 pdf2zh-desktop-win 文件夹。"""
    if platform_key() == "mac":
        if not getattr(sys, "frozen", False):
            return None
        root = Path(sys.executable).resolve().parents[2]
        return root if root.suffix == ".app" else None
    root = Path(__file__).resolve().parents[3]   # <根>/core/site-packages/pdf2zh/self_update.py
    if (root / "_launcher.py").exists() and (root / "core" / "runtime" / "pythonw.exe").exists():
        return root
    return None


def state_dir(root=None):
    """暂存、日志、结果放在哪：Windows 放安装目录下 _update（同盘，换文件快）；macOS 放用户缓存目录"""
    if platform_key() == "mac":
        d = Path.home() / "Library" / "Caches" / "pdf2zh-update"
    else:
        root = root or install_root()
        d = (root / "_update") if root else Path(tempfile.gettempdir()) / "pdf2zh-update"
    d.mkdir(parents=True, exist_ok=True)
    return d


def can_install(root=None):
    """能不能自动替换。返回 (True, "") 或 (False, 给用户看的原因)"""
    root = root or install_root()
    if root is None:
        return False, "当前不是安装版，不能自动更新"
    if platform_key() == "mac":
        if "/AppTranslocation/" in str(root):
            return False, "请先把 pdf2zh 拖进「应用程序」文件夹再打开，之后才能自动更新"
        if not (os.access(str(root.parent), os.W_OK) and os.access(str(root), os.W_OK)):
            return False, f"没有写入权限：{root.parent}"
        return True, ""
    try:
        probe = root / "_update" / ".write_test"
        probe.parent.mkdir(parents=True, exist_ok=True)
        probe.write_text("ok")
        probe.unlink()
    except Exception:
        return False, f"没有写入权限：{root}（请把软件放在桌面或文档等自己的文件夹里）"
    return True, ""


def _log(msg, root=None):
    try:
        with open(state_dir(root) / "update.log", "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(msg) + "\n")
    except Exception:
        pass


# ───────────────────────── 检查 ─────────────────────────

def manifest_sources(plat=None):
    plat = plat or platform_key()
    srcs = []
    env = os.environ.get(ENV_MANIFEST, "").strip()
    if env:
        srcs.append(env)
    srcs.append(f"{RELEASE_BASE}/latest/download/update-{plat}.json")
    return srcs


def _latest_via_api(timeout=8):
    """没有清单时（网络只通 API、或旧版 Release）至少拿到最新版本号，供手动下载提示用"""
    import urllib.request
    req = urllib.request.Request(
        "https://api.github.com/repos/AaronGIG/pdf2zh-desktop/releases/latest",
        headers={"Accept": "application/vnd.github+json", "User-Agent": UA})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        data = json.loads(r.read().decode())
    return (data.get("tag_name") or "").lstrip("vV").strip(), data.get("html_url") or f"{RELEASE_BASE}/latest"


def check(current_version, plat=None, timeout=15):
    """返回 dict：version / notes / release_url / newer / mode（none | patch | manual）。
    mode=patch 时另有 manifest / changed / deleted；manual 时 reason 说明为什么不能自动装。"""
    plat = plat or platform_key()
    data, src, last = None, None, None
    for s in manifest_sources(plat):
        try:
            d = json.loads(_read(s, timeout).decode("utf-8"))
            if d.get("platform") == plat and d.get("version"):
                data, src = d, s
                break
        except Exception as e:
            last = e
    if data is None:
        ver, url = _latest_via_api()
        if not ver:
            raise UpdateError(f"取不到更新信息：{last}")
        return {"version": ver, "notes": "", "release_url": url,
                "newer": vtuple(ver) > vtuple(current_version), "mode": "manual",
                "reason": "这个版本没有自动更新包"}
    ver = str(data["version"])
    info = {"version": ver, "notes": data.get("notes", ""),
            "release_url": data.get("release_url") or f"{RELEASE_BASE}/tag/v{ver}",
            "newer": vtuple(ver) > vtuple(current_version), "mode": "none"}
    if not info["newer"]:
        return info
    base = (data.get("bases") or {}).get(str(current_version))
    hashes = (data.get("patch") or {}).get("hashes") or {}
    if _failed_before(ver):
        info.update(mode="manual", reason="上次自动更新没有成功")
    elif base is None:
        info.update(mode="manual", reason="这次更新需要下载完整安装包")
    elif not all(f in hashes for f in base.get("changed", [])):
        info.update(mode="manual", reason="更新包不完整")
    else:
        info.update(mode="patch", manifest=data, manifest_src=src,
                    changed=list(base.get("changed", [])), deleted=list(base.get("deleted", [])))
    return info


# ───────────────────────── 下载 + 暂存 ─────────────────────────

def _asset_sources(manifest, manifest_src, name):
    srcs = []
    for base in manifest.get("mirrors") or []:
        srcs.append(base.rstrip("/") + "/" + name)
    # 清单从哪来，增量包就先从同一个地方找（测试时清单在本地目录）
    if manifest_src:
        if _is_url(manifest_src):
            u = manifest_src.rsplit("/", 1)[0] + "/" + name
            if "/latest/download/" not in u:
                srcs.insert(0, u)
        else:
            srcs.insert(0, str(Path(manifest_src).parent / name))
    srcs.append(f"{RELEASE_BASE}/download/v{manifest['version']}/{name}")
    seen, out = set(), []
    for s in srcs:
        if s not in seen:
            seen.add(s); out.append(s)
    return out


def download(sources, dest, size, sha256, progress=None, cancel=None):
    """断点续传下载，校验大小和 sha256；多个来源依次尝试，每个来源重试 3 次"""
    dest = Path(dest)
    part = dest.with_name(dest.name + ".part")
    if dest.exists() and dest.stat().st_size == size and sha256_file(dest) == sha256:
        return dest
    last = None
    for src in sources:
        for attempt in range(3):
            try:
                have = part.stat().st_size if part.exists() else 0
                if have > size:
                    part.unlink(); have = 0
                if have < size:
                    if _is_url(src):
                        import urllib.request
                        headers = {"User-Agent": UA}
                        if have:
                            headers["Range"] = f"bytes={have}-"
                        resp = urllib.request.urlopen(urllib.request.Request(src, headers=headers), timeout=30)
                        if have and getattr(resp, "status", 200) != 206:
                            have = 0   # 服务器不支持续传，从头来
                    else:
                        resp = open(src, "rb")
                        resp.seek(have)
                    with resp, open(part, "ab" if have else "wb") as f:
                        while True:
                            if cancel and cancel():
                                raise UpdateCancelled("已取消")
                            chunk = resp.read(256 * 1024)
                            if not chunk:
                                break
                            f.write(chunk)
                            have += len(chunk)
                            if progress:
                                progress(min(have, size), size)
                if part.stat().st_size == size and sha256_file(part) == sha256:
                    os.replace(part, dest)
                    return dest
                part.unlink()
                last = "文件校验不一致"
            except UpdateCancelled:
                raise
            except Exception as e:
                last = e
                time.sleep(1.5)
    raise UpdateError(f"下载更新包失败：{last}")


def _safe_target(base, rel):
    t = (base / rel).resolve()
    if not str(t).startswith(str(base.resolve()) + os.sep):
        raise UpdateError(f"更新包里有不合法的路径：{rel}")
    return t


def prepare(info, progress=None, cancel=None, root=None):
    """下载增量包，把本机需要的文件解到暂存目录并逐个校验。返回暂存信息（同 pending()）"""
    if info.get("mode") != "patch":
        raise UpdateError("这个版本不能自动更新")
    m = info["manifest"]
    patch = m["patch"]
    sd = state_dir(root)
    dl_dir = sd / "downloads"
    dl_dir.mkdir(parents=True, exist_ok=True)
    for old in dl_dir.iterdir():                     # 只留当前要用的包，旧版本的包清掉
        if not old.name.startswith(patch["name"]):
            if old.is_dir():
                shutil.rmtree(old, ignore_errors=True)
            else:
                old.unlink()
    zpath = download(_asset_sources(m, info.get("manifest_src"), patch["name"]),
                     dl_dir / patch["name"], int(patch["size"]), patch["sha256"], progress, cancel)
    staging = sd / "staging"
    shutil.rmtree(staging, ignore_errors=True)
    files_dir = staging / "files"
    files_dir.mkdir(parents=True)
    hashes = patch["hashes"]
    with zipfile.ZipFile(zpath) as zf:
        for rel in info["changed"]:
            if cancel and cancel():
                raise UpdateCancelled("已取消")
            zi = zf.getinfo(rel)
            target = _safe_target(files_dir, rel)
            target.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(zi) as src, open(target, "wb") as dst:
                shutil.copyfileobj(src, dst, 1024 * 1024)
            mode = (zi.external_attr >> 16) & 0o777
            if mode:
                os.chmod(target, mode)
            if sha256_file(target) != hashes[rel]:
                raise UpdateError(f"更新包里的文件校验不一致：{rel}")
    ready = {"version": info["version"], "notes": info.get("notes", ""),
             "release_url": info.get("release_url", ""),
             "changed": info["changed"], "deleted": info["deleted"],
             "hashes": {r: hashes[r] for r in info["changed"]}, "time": int(time.time())}
    (staging / "deleted.txt").write_text("\n".join(info["deleted"]) + "\n", encoding="utf-8")
    (staging / "ready.json").write_text(json.dumps(ready, ensure_ascii=False, indent=1), encoding="utf-8")
    _log(f"已下载并暂存 v{info['version']}（{len(info['changed'])} 个文件）", root)
    return ready


def pending(current_version, root=None):
    """已经下载好、还没换上的新版本信息；没有返回 None"""
    try:
        p = state_dir(root) / "staging" / "ready.json"
        if not p.exists():
            return None
        r = json.loads(p.read_text(encoding="utf-8"))
        if vtuple(r.get("version")) > vtuple(current_version) and not _failed_before(r.get("version"), root):
            return r
    except Exception:
        pass
    return None


# ───────────────────────── 换上新版本 ─────────────────────────

_MAC_APPLIER = r'''#!/bin/bash
# pdf2zh 一键更新（macOS）：等主程序退出 → 克隆当前 App → 放入新文件 → codesign 校验 → 整包换上
APP="$1"; FILES="$2"; PID="$3"; RELAUNCH="$4"; STATE="$5"; VERSION="$6"; FROMV="$7"
LOG="$STATE/update.log"; DEL="$STATE/staging/deleted.txt"
exec >>"$LOG" 2>&1
echo "== $(date '+%F %T') 开始更新 v$FROMV -> v$VERSION"
result() { printf '{"ok": %s, "version": "%s", "from": "%s", "error": "%s", "time": %s}\n' "$1" "$VERSION" "$FROMV" "$2" "$(date +%s)" > "$STATE/result.json"; echo "结果: $1 $2"; }
for i in $(seq 1 240); do kill -0 "$PID" 2>/dev/null || break; sleep 0.5; done
if kill -0 "$PID" 2>/dev/null; then result false "app-still-running"; exit 1; fi
PARENT="$(dirname "$APP")"; NAME="$(basename "$APP" .app)"
NEW="$PARENT/.$NAME.updating.app"
rm -rf "$NEW"
if ! cp -Rpc "$APP" "$NEW" 2>/dev/null; then
  rm -rf "$NEW"
  ditto "$APP" "$NEW" || { rm -rf "$NEW"; result false "copy-failed"; exit 1; }
fi
ditto "$FILES" "$NEW" || { rm -rf "$NEW"; result false "patch-failed"; exit 1; }
if [ -f "$DEL" ]; then
  while IFS= read -r rel; do [ -n "$rel" ] && rm -f "$NEW/$rel"; done < "$DEL"
fi
if ! /usr/bin/codesign --verify --deep "$NEW"; then rm -rf "$NEW"; result false "codesign-verify-failed"; exit 1; fi
/usr/bin/xattr -dr com.apple.quarantine "$NEW" 2>/dev/null
rm -rf "$STATE/backup"; mkdir -p "$STATE/backup"
BAK="$STATE/backup/$NAME.app"
if ! mv "$APP" "$BAK" 2>/dev/null; then
  BAK="$PARENT/.$NAME.old.app"; rm -rf "$BAK"
  mv "$APP" "$BAK" || { rm -rf "$NEW"; result false "move-old-failed"; exit 1; }
fi
if ! mv "$NEW" "$APP"; then mv "$BAK" "$APP"; rm -rf "$NEW"; result false "swap-failed"; exit 1; fi
touch "$APP"
rm -rf "$STATE/staging"
result true ""
if [ "$RELAUNCH" = "1" ]; then /usr/bin/open "$APP"; fi
exit 0
'''


def launch_apply(current_version, relaunch, root=None):
    """启动独立的替换程序后立刻返回；调用方随后退出本程序。成功启动返回 True"""
    root = root or install_root()
    ok, why = can_install(root)
    if not ok:
        raise UpdateError(why)
    r = pending(current_version, root)
    if not r:
        raise UpdateError("没有已下载好的新版本")
    sd = state_dir(root)
    try:
        (sd / "result.json").unlink()
    except FileNotFoundError:
        pass
    files_dir = sd / "staging" / "files"
    pid = os.getpid()
    _log(f"启动替换程序：v{current_version} -> v{r['version']}，完成后{'重新打开' if relaunch else '不打开'}", root)
    if platform_key() == "mac":
        script = sd / "apply.sh"
        script.write_text(_MAC_APPLIER, encoding="utf-8")
        os.chmod(script, 0o755)
        subprocess.Popen(["/bin/bash", str(script), str(root), str(files_dir), str(pid),
                          "1" if relaunch else "0", str(sd), r["version"], str(current_version)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True, close_fds=True)
        return True
    # Windows：运行环境复制到临时目录再跑替换（安装目录里的正被本程序占用）
    tmp = Path(tempfile.gettempdir()) / f"pdf2zh_update_{pid}"
    shutil.rmtree(tmp, ignore_errors=True)
    shutil.copytree(root / "core" / "runtime", tmp / "runtime")
    shutil.copy2(__file__, tmp / "pdf2zh_apply.py")
    params = {"root": str(root), "files": str(files_dir), "pid": pid, "relaunch": bool(relaunch),
              "state": str(sd), "version": r["version"], "from": str(current_version),
              "changed": r["changed"], "deleted": r["deleted"], "hashes": r["hashes"], "tmp": str(tmp)}
    pfile = tmp / "params.json"
    pfile.write_text(json.dumps(params, ensure_ascii=False), encoding="utf-8")
    flags = 0x00000008 | 0x00000200   # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    subprocess.Popen([str(tmp / "runtime" / "pythonw.exe"), str(tmp / "pdf2zh_apply.py"), "--apply", str(pfile)],
                     cwd=str(tmp), creationflags=flags, close_fds=True,
                     stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return True


def _retry(fn, *a, tries=20, delay=0.5):
    for i in range(tries):
        try:
            return fn(*a)
        except PermissionError:   # 杀毒软件扫描、资源管理器预览会短暂占用文件
            if i == tries - 1:
                raise
            time.sleep(delay)


def apply_files(root, files_dir, changed, deleted, hashes, backup_dir):
    """逐个文件：先备份旧文件 → 写到同目录临时名 → 原子改名替换 → 校验。任何一步失败按备份还原。"""
    root, files_dir, backup_dir = Path(root), Path(files_dir), Path(backup_dir)
    done = []   # (动作, 目标, 备份)
    try:
        for rel in changed:
            src = files_dir / rel
            dst = _safe_target(root, rel)
            bak = backup_dir / rel
            had = dst.exists()
            if had:
                bak.parent.mkdir(parents=True, exist_ok=True)
                _retry(shutil.copy2, str(dst), str(bak))
            dst.parent.mkdir(parents=True, exist_ok=True)
            if had and not os.access(str(dst), os.W_OK):
                os.chmod(str(dst), stat.S_IREAD | stat.S_IWRITE)   # 只读文件先去掉只读
            tmp = dst.with_name(dst.name + ".pdf2zh-new")
            try:
                _retry(shutil.copy2, str(src), str(tmp))
                _retry(os.replace, str(tmp), str(dst))
            finally:
                if tmp.exists():
                    try:
                        tmp.unlink()
                    except Exception:
                        pass
            done.append(("replace", dst, bak if had else None))
            if sha256_file(dst) != hashes[rel]:
                raise UpdateError(f"写入后校验不一致：{rel}")
        for rel in deleted:
            dst = _safe_target(root, rel)
            if dst.exists():
                bak = backup_dir / rel
                bak.parent.mkdir(parents=True, exist_ok=True)
                _retry(shutil.move, str(dst), str(bak))
                done.append(("delete", dst, bak))
    except Exception:
        for action, dst, bak in reversed(done):
            try:
                if action == "replace":
                    if bak is not None:
                        _retry(shutil.copy2, str(bak), str(dst))
                    else:
                        dst.unlink()
                else:
                    _retry(shutil.move, str(bak), str(dst))
            except Exception:
                pass
        raise


def _wait_pid_exit(pid, timeout_s=120):
    if platform_key() != "win":
        end = time.time() + timeout_s
        while time.time() < end:
            try:
                os.kill(pid, 0)
            except OSError:
                return True
            time.sleep(0.5)
        return False
    import ctypes
    k32 = ctypes.windll.kernel32
    h = k32.OpenProcess(0x00100000, False, int(pid))   # SYNCHRONIZE
    if not h:
        return True   # 进程已经不在了
    try:
        return k32.WaitForSingleObject(h, int(timeout_s * 1000)) == 0
    finally:
        k32.CloseHandle(h)


def _main_apply(pfile):
    """Windows 替换程序入口（在临时目录的运行环境里执行）"""
    p = json.loads(Path(pfile).read_text(encoding="utf-8"))
    root, sd = Path(p["root"]), Path(p["state"])
    marker = sd / "applying"

    def log(msg):
        try:
            with open(sd / "update.log", "a", encoding="utf-8") as f:
                f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + msg + "\n")
        except Exception:
            pass

    def result(ok, err=""):
        (sd / "result.json").write_text(json.dumps(
            {"ok": ok, "version": p["version"], "from": p["from"], "error": err, "time": int(time.time())},
            ensure_ascii=False), encoding="utf-8")
        log(f"结果: {ok} {err}")

    log(f"== 开始更新 v{p['from']} -> v{p['version']}")
    try:
        marker.write_text(str(time.time()))
        if not _wait_pid_exit(p["pid"], 120):
            result(False, "主程序 2 分钟没有退出")
            return
        time.sleep(0.5)
        backup = sd / "backup"
        shutil.rmtree(backup, ignore_errors=True)
        apply_files(root, p["files"], p["changed"], p["deleted"], p["hashes"], backup)
        shutil.rmtree(sd / "staging", ignore_errors=True)
        result(True)
    except Exception as e:
        result(False, f"{type(e).__name__}: {e}")
    finally:
        try:
            marker.unlink()
        except Exception:
            pass
        if p.get("relaunch"):
            try:
                subprocess.Popen([str(root / "core" / "runtime" / "pythonw.exe"), str(root / "_launcher.py")],
                                 cwd=str(root), creationflags=0x00000008 | 0x00000200, close_fds=True)
            except Exception as e:
                log(f"重新打开失败: {e}")


# ───────────────────────── 界面用的后台线程 ─────────────────────────

_WORKER_CLS = None


def qt_worker_class():
    """Mac / Win 界面共用的后台线程类。PyQt5 在这里才导入：替换程序在 Windows 上用的是
    裸运行环境（没有 PyQt5），模块顶层不能依赖它。

    state 信号：(种类, 数据)
      none        已是最新                 error      检查失败（网络等）
      manual      有新版但只能手动下载（数据里 reason 说明原因）
      available   有新版、能自动装，但没开自动下载（等用户点）
      downloading 开始下载   progress  下载百分比   ready  已下载好、重启或退出时换上
      failed      下载/校验失败
    """
    global _WORKER_CLS
    if _WORKER_CLS is not None:
        return _WORKER_CLS
    from PyQt5.QtCore import QThread, pyqtSignal

    class AutoUpdateWorker(QThread):
        state = pyqtSignal(str, object)

        def __init__(self, current_version, download=True, parent=None):
            super().__init__(parent)
            self.setStackSize(16 * 1024 * 1024)
            self.current_version = current_version
            self.download = download
            self._cancel = False

        def cancel(self):
            self._cancel = True

        def run(self):
            try:
                info = check(self.current_version)
            except Exception as e:
                self.state.emit("error", str(e))
                return
            if not info.get("newer"):
                self.state.emit("none", info)
                return
            if info.get("mode") == "patch":
                ok, why = can_install()
                if not ok:
                    info = dict(info, mode="manual", reason=why)
            if info.get("mode") != "patch":
                self.state.emit("manual", info)
                return
            if _failed_before(info["version"]):
                self.state.emit("manual", dict(info, mode="manual", reason="上次自动更新没有成功"))
                return
            ready = pending(self.current_version)
            if ready and ready.get("version") == info["version"]:
                self.state.emit("ready", ready)
                return
            if not self.download:
                self.state.emit("available", info)
                return
            self.state.emit("downloading", info)
            last = [-1]

            def prog(done, total):
                pct = int(done * 100 / max(total, 1))
                if pct != last[0]:
                    last[0] = pct
                    self.state.emit("progress", pct)
            try:
                self.state.emit("ready", prepare(info, progress=prog, cancel=lambda: self._cancel))
            except Exception as e:
                _log(f"下载 v{info['version']} 失败：{e}")
                self.state.emit("failed", {"info": info, "error": str(e)})

    _WORKER_CLS = AutoUpdateWorker
    return _WORKER_CLS


def busy_translating_hint():
    return "正在翻译，等这次翻译完成后再点「重启更新」。\n（不点也行：下次退出软件时会自动换上新版本。）"


# ───────────────────────── 启动时 ─────────────────────────

def _failed_before(version, root=None):
    try:
        f = state_dir(root) / "failed.json"
        return f.exists() and str(version) in json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        return False


def on_startup(current_version, root=None):
    """新版本启动时调用：返回上次替换的结果（{"ok", "version", "error"}，没有则 None），并清理暂存/备份。
    替换失败的版本记进 failed.json，之后不再自动尝试，改为提示手动下载。"""
    if install_root() is None and root is None:
        return None
    sd = state_dir(root)
    res = None
    rf = sd / "result.json"
    try:
        if rf.exists():
            res = json.loads(rf.read_text(encoding="utf-8"))
            rf.unlink()
            if not res.get("ok"):
                ff = sd / "failed.json"
                failed = json.loads(ff.read_text(encoding="utf-8")) if ff.exists() else []
                if res.get("version") not in failed:
                    failed.append(res.get("version"))
                ff.write_text(json.dumps(failed), encoding="utf-8")
                shutil.rmtree(sd / "staging", ignore_errors=True)   # 换不上的版本不留着，避免再提示「重启更新」
            _log(f"启动 v{current_version}，上次更新结果：{res}", root)
    except Exception:
        res = None
    try:
        r = sd / "staging" / "ready.json"
        if r.exists() and vtuple(json.loads(r.read_text(encoding="utf-8")).get("version")) <= vtuple(current_version):
            shutil.rmtree(sd / "staging", ignore_errors=True)
        if res and res.get("ok") and str(res.get("version")) == str(current_version):
            shutil.rmtree(sd / "backup", ignore_errors=True)
            shutil.rmtree(sd / "downloads", ignore_errors=True)
            if platform_key() == "mac":
                rt = install_root()
                if rt is not None:
                    shutil.rmtree(rt.parent / f".{rt.stem}.old.app", ignore_errors=True)
        if platform_key() == "win":   # 替换程序用过的临时运行环境（它没法删自己）
            for t in Path(tempfile.gettempdir()).glob("pdf2zh_update_*"):
                if t.is_dir() and t.name != f"pdf2zh_update_{os.getpid()}":
                    shutil.rmtree(t, ignore_errors=True)
    except Exception:
        pass
    if res and str(res.get("version")) != str(current_version) and res.get("ok"):
        return None   # 结果不属于这次启动的版本（例如用户又手动装回了旧版），不提示
    return res


if __name__ == "__main__" and len(sys.argv) >= 3 and sys.argv[1] == "--apply":
    _main_apply(sys.argv[2])
